<?php require_once "../config/auth.php";requireAdmin();require_once "../config/database.php";$clubs=$conn->query('SELECT club_id,club_name FROM clubs ORDER BY club_name');$cid=(int)($_GET['club_id']??0);$rows=null;if($cid){$s=$conn->prepare('SELECT u.name,u.register_no,u.email,u.department,u.year,cm.joined_at FROM club_members cm JOIN users u ON u.id=cm.user_id WHERE cm.club_id=? ORDER BY u.name');$s->bind_param('i',$cid);$s->execute();$rows=$s->get_result();}?>
<!doctype html><html><head><title>Club Members</title><link rel="stylesheet" href="../css/style.css"></head><body><nav class="navbar"><div class="logo">Admin</div><div class="nav-links"><a href="dashboard.php">Dashboard</a><a href="manage-clubs.php">Clubs</a><a href="../logout.php">Logout</a></div></nav><div class="container"><h1>View Club Members</h1><form class="search"><select name="club_id" required><?php while($c=$clubs->fetch_assoc()):?><option value="<?=$c['club_id']?>" <?=$cid==$c['club_id']?'selected':''?>><?=htmlspecialchars($c['club_name'])?></option><?php endwhile;?></select><button class="btn">View</button></form><?php if($rows):?><div class="table-box table-wrap"><table class="data-table"><tr><th>Name</th><th>Register No</th><th>Email</th><th>Department</th><th>Year</th><th>Joined</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['register_no'])?></td><td><?=htmlspecialchars($r['email'])?></td><td><?=htmlspecialchars($r['department'])?></td><td><?=$r['year']?></td><td><?=$r['joined_at']?></td></tr><?php endwhile;?></table></div><?php endif;?></div></body></html>
